/* Digi Puzzles — redact engine. One copy serves every redact page in reports/.
   Redact: an n×n grid full of letters, some of them decoys where the black squares
   belong. Tap a letter to black it out; when the black set is right every across
   and down run is a word. Built 6 Nov 2026 for Lab on the house chrome.
   The page supplies window.DN_PUZZLE = {type:"redact", id:"DP·REDA·0001", band, n,
   letters:"n² capitals", black:[cell…], words:[…], seed}. Generator and gate:
   tools/redact.js. Keep element ids and localStorage keys stable. */
/* dn-core:start (generated by tools/sync-core.js) */
'use strict';
/* Shared calendar and completed-save rules. Node tools require this file;
   browsers receive identical bundled copies via tools/sync-core.js. Keep the
   existing storage keys, ids and record formats; never redate old results. */
(function(root,factory){
 if(typeof module==='object'&&module.exports)module.exports=factory(root);
 else if(!root.dnCore)root.dnCore=factory(root);
})(typeof globalThis==='object'?globalThis:this,function(root){
 function londonDay(instant){
  const d=instant===undefined?new Date():new Date(instant);
  try{
   const p={};
   new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/London',year:'numeric',month:'2-digit',day:'2-digit'})
    .formatToParts(d).forEach(x=>{p[x.type]=x.value;});
   return p.year+'-'+p.month+'-'+p.day;
  }catch(e){return d.toISOString().slice(0,10);}
 }
 function dayBefore(day){
  const d=new Date(day+'T12:00:00Z');d.setUTCDate(d.getUTCDate()-1);return d.toISOString().slice(0,10);
 }
 const object=x=>!!x&&typeof x==='object'&&!Array.isArray(x);
 // Track actual game-save failures only. No storage probes, timers or global
 // Storage patching. Pending data lives in this tab until a real write succeeds.
 const scopes=new WeakMap(),listeners=new Set();
 function scope(storage){
  const owner=storage||root;
  if(!scopes.has(owner))scopes.set(owner,{issues:new Map(),done:new Map()});
  return scopes.get(owner);
 }
 function changed(storage){if(!storage)listeners.forEach(fn=>{try{fn();}catch(e){}});}
 function failed(key,retry,storage){const issues=scope(storage).issues,was=issues.has(key);issues.set(key,retry);if(!was)changed(storage);}
 function saved(key,storage){if(scope(storage).issues.delete(key))changed(storage);}
 function saveIssues(){return scope().issues.size;}
 function onSaveChange(fn){listeners.add(fn);return ()=>listeners.delete(fn);}
 async function retrySaves(){
  for(const retry of Array.from(scope().issues.values())){try{await retry();}catch(e){}}
  return saveIssues()===0;
 }
 function read(key,storage){
  try{const s=JSON.parse((storage||root.localStorage).getItem(key)||'null');return object(s)&&s.v===1?s:null;}
  catch(e){return null;}
 }
 function getDone(key,id,storage){const s=read(key,storage),pending=scope(storage).done.get(key);return s&&object(s.done)&&s.done[id]||pending&&pending[id]||null;}
 function putDone(key,id,rec,storage){
  const state=scope(storage),pending=state.done.get(key)||{};
  const s=read(key,storage)||{v:1};if(!object(s.done))s.done={};
  if(s.done[id]&&!Object.keys(pending).length)return s.done[id];
  const first=s.done[id]||pending[id]||Object.assign({},rec,{d:londonDay()});
  pending[id]=first;state.done.set(key,pending);
  if(Object.keys(pending).every(k=>s.done[k])){state.done.delete(key);saved(key,storage);return first;}
  s.done=Object.assign({},pending,s.done);
  try{
   (storage||root.localStorage).setItem(key,JSON.stringify(s));
   state.done.delete(key);saved(key,storage);return first;
  }catch(e){failed(key,()=>putDone(key,id,first,storage),storage);return null;}
 }
 function mergeStreak(a,b){
  a=object(a)?a:{};b=object(b)?b:{};
  const valid=s=>/^\d{4}-\d{2}-\d{2}$/.test(s.last||'');
  const newer=valid(b)&&(!valid(a)||b.last>a.last)?b:a,older=newer===a?b:a;
  let n=Number(newer.n)||0;
  if(valid(newer)&&valid(older)){
   if(newer.last===older.last)n=Math.max(n,Number(older.n)||0);
   else if(dayBefore(newer.last)===older.last)n=Math.max(n,(Number(older.n)||0)+1);
  }
  return Object.assign({},older,newer,{n,best:Math.max(n,Number(a.best)||0,Number(b.best)||0)});
 }
 function mergeProgress(current,stored,activeId){
  if(!stored)return current;
  const merged=Object.assign({},stored,current);
  // The stored result was committed first. Replaying or an older tab cannot
  // replace it; new ids from either tab survive. Other save fields stay intact.
  merged.done=Object.assign({},object(current.done)?current.done:{},object(stored.done)?stored.done:{});
  if(object(current.days)||object(stored.days)){
   merged.days=Object.assign({},object(current.days)?current.days:{},object(stored.days)?stored.days:{});
   const local=object(current.days)&&current.days[activeId],remote=object(stored.days)&&stored.days[activeId];
   if(local&&(!remote||remote.state!=='done'))merged.days[activeId]=local;
  }
  if(current.streak||stored.streak)merged.streak=mergeStreak(current.streak,stored.streak);
  if('best' in current||'best' in stored)merged.best=Math.max(Number(current.best)||0,Number(stored.best)||0);
  return merged;
 }
 function same(a,b){
  if(a===b)return true;
  if(!a||!b||typeof a!=='object'||typeof b!=='object'||Array.isArray(a)!==Array.isArray(b))return false;
  const keys=Object.keys(a);
  return keys.length===Object.keys(b).length&&keys.every(k=>Object.prototype.hasOwnProperty.call(b,k)&&same(a[k],b[k]));
 }
 function progressOnly(s){
  s=s||{};
  const days=Object.fromEntries(Object.entries(s.days||{}).filter(([,d])=>d&&d.state!=='ready'));
  return {done:s.done||{},days,cur:s.cur||null,streak:s.streak&&s.streak.last?s.streak:null,best:s.best||0};
 }
 function saveProgress(key,current,activeId,storage,report=true){
  // Merge even if writing fails, so the current tab retains the results it read.
  let pending=report;
  try{
   const stored=read(key,storage);
   Object.assign(current,mergeProgress(current,stored,activeId));
   if(stored&&same(current,stored)){saved(key,storage);return current;}
   // A later housekeeping/settings write must not warn about game data that
   // is already durable. Compare data, not property order or storage capacity.
   pending=report&&!same(progressOnly(current),progressOnly(stored));
   (storage||root.localStorage).setItem(key,JSON.stringify(current));saved(key,storage);
  }catch(e){if(pending||scope(storage).issues.has(key))failed(key,()=>saveProgress(key,current,activeId,storage,true),storage);}
  return current;
 }
 async function saveStreak(key,value,external){
  try{external=external===undefined?root.storage:external;if(external){await external.set(key,JSON.stringify(value));saved(key);return true;}}catch(e){}
  try{root.localStorage.setItem(key,JSON.stringify(value));saved(key);return true;}
  catch(e){failed(key,()=>saveStreak(key,value,external));return false;}
 }
 return {londonDay,dayBefore,getDone,putDone,mergeProgress,saveProgress,saveStreak,saveIssues,onSaveChange,retrySaves};
});
/* dn-core:end */

window.dnFinish=window.dnFinish||{q:[],show(c){this.q.push(c)},hide(){}};
document.write('<link rel="stylesheet" href="../engines/finish.css"><link rel="stylesheet" href="../engines/house.css"><script src="../engines/finish.js"><\/script><script src="../engines/house.js"><\/script>');
(function(){
"use strict";
const PUZZLE=window.DN_PUZZLE;
const N=PUZZLE.n,K=PUZZLE.black.length,ANSWER=PUZZLE.black.slice().sort((a,b)=>a-b).join();
const $=id=>document.getElementById(id);
const gridEl=$("grid"),msgEl=$("msg"),timerEl=$("timer");
const meta=n=>{const m=document.querySelector('meta[name="'+n+'"]');return m?m.content:"";};
const LAB=!!meta("dn:badge");

/* ---------- ship gate at load: the answer must be a proper crossword ---------- */
function runsOf(cells,black){const out=[];let cur=[];for(const c of cells){if(black.has(c)){if(cur.length)out.push(cur);cur=[];}else cur.push(c);}if(cur.length)out.push(cur);return out;}
const LINES=[];for(let r=0;r<N;r++)LINES.push([...Array(N).keys()].map(c=>r*N+c));for(let c=0;c<N;c++)LINES.push([...Array(N).keys()].map(r=>r*N+c));
function gate(p){
  const errs=[];
  if(!p||!Number.isInteger(p.n)||typeof p.letters!=="string"||p.letters.length!==p.n*p.n||!/^[A-Z]+$/.test(p.letters)||!Array.isArray(p.black))return["malformed board"];
  const black=new Set(p.black),words=[];
  for(const line of LINES)for(const run of runsOf(line,black)){if(run.length<3)errs.push("a run of "+run.length);words.push(run.map(c=>p.letters[c]).join("").toLowerCase());}
  if(Array.isArray(p.words)&&words.join()!==p.words.join())errs.push("the words don't match the grid");
  return errs;
}
const GATE=gate(PUZZLE);
if(GATE.length){msgEl.textContent="This board failed its check and can't be played: "+GATE.join("; ");throw new Error("redact gate: "+GATE.join("; "));}

/* ---------- streak (digi-redact-streak, London days) ---------- */
const STREAK_KEY="digi-redact-streak",DONE_KEY="digi-redact-v1";
function today(){return window.dnCore.londonDay();}
function dayBefore(s){return window.dnCore.dayBefore(s);}
function streakGet(){try{const s=JSON.parse(localStorage.getItem(STREAK_KEY)||"null");return s&&typeof s==="object"?s:null;}catch(e){return null;}}
function streakLive(){const s=streakGet(),t=today();return s&&(s.last===t||s.last===dayBefore(t))?(s.streak||0):0;}
function streakBump(){
  const s=streakGet()||{last:null,streak:0,best:0,dates:[]},t=today();
  if(!(s.dates||[]).includes(t)){
    s.streak=s.last===dayBefore(t)?(s.streak||0)+1:1;s.best=Math.max(s.best||0,s.streak);
    s.last=t;s.tz="L";s.dates=[...new Set([...(s.dates||[]),t])].slice(-90);
    window.dnCore.saveStreak(STREAK_KEY,s,null);
  }
  return s.streak||0;
}

/* ---------- state ---------- */
const state={black:new Set(),hist:[],taps:0,misses:0,secs:0,t0:null,timer:null,solved:false,streak:streakLive(),resumed:false};
$("streakn").textContent=state.streak;
const NUM=parseInt(String(PUZZLE.id).split("·").pop(),10);
$("pid").textContent="Redact "+NUM;
if($("pband"))$("pband").textContent=LAB?"Lab":"Medium";
$("modalsub").textContent=PUZZLE.id;
gridEl.style.setProperty("--n",N);
function fmt(s){s=Math.max(0,Math.round(s));return Math.floor(s/60)+":"+String(s%60).padStart(2,"0");}
function setMsg(t){msgEl.textContent=t;}

/* ---------- clock ---------- */
function startTimer(){
  if(state.solved||state.timer)return;
  state.t0=Date.now();timerEl.classList.remove("waiting");
  state.timer=setInterval(()=>{timerEl.textContent=fmt(state.secs+(Date.now()-state.t0)/1000);},250);
}
function stopTimer(){if(state.timer){clearInterval(state.timer);state.timer=null;}if(state.t0){state.secs+=(Date.now()-state.t0)/1000;state.t0=null;}}
window.addEventListener("dn:play",()=>{if(!state.solved)startTimer();});
document.addEventListener("visibilitychange",()=>{
  if(state.solved)return;
  if(document.hidden){const was=!!state.timer;stopTimer();state.away=was;timerEl.classList.add("waiting");saveCur();}
  else if(state.away){state.away=false;startTimer();}
});
window.addEventListener("pagehide",()=>{if(!state.solved){stopTimer();saveCur();}});
timerEl.classList.add("waiting");

/* ---------- an unfinished board is kept in digi-redact-v1.cur ---------- */
function readSave(){try{const s=JSON.parse(localStorage.getItem(DONE_KEY)||"null");return s&&typeof s==="object"?s:{v:1};}catch(e){return {v:1};}}
function saveCur(){
  if(state.solved||window.dnCore.getDone(DONE_KEY,PUZZLE.id))return;
  try{const s=readSave();
    if(state.taps)s.cur={id:PUZZLE.id,b:[...state.black],t:state.taps,m:state.misses,s:Math.round(state.secs+(state.t0?(Date.now()-state.t0)/1000:0)),at:Date.now()};
    else if(s.cur&&s.cur.id===PUZZLE.id)delete s.cur;
    else return;
    if(!s.v)s.v=1;localStorage.setItem(DONE_KEY,JSON.stringify(s));
  }catch(e){}
}
function clearCur(){try{const s=readSave();if(s.cur&&s.cur.id===PUZZLE.id){delete s.cur;localStorage.setItem(DONE_KEY,JSON.stringify(s));}}catch(e){}}
function restoreCur(){
  const c=readSave().cur;
  if(!c||c.id!==PUZZLE.id||!Array.isArray(c.b))return;
  state.black=new Set(c.b.filter(i=>Number.isInteger(i)&&i>=0&&i<N*N));state.taps=+c.t||0;state.misses=+c.m||0;state.secs=+c.s||0;state.resumed=true;timerEl.textContent=fmt(state.secs);
}

/* ---------- the board ---------- */
const cells=[];
function build(){
  gridEl.innerHTML="";cells.length=0;
  for(let i=0;i<N*N;i++){
    const b=document.createElement("button");b.type="button";b.className="cell";b.setAttribute("role","gridcell");b.dataset.i=i;
    b.textContent=PUZZLE.letters[i];
    b.addEventListener("click",()=>tap(i));
    gridEl.appendChild(b);cells.push(b);
  }
}
function paint(){
  cells.forEach((c,i)=>{const on=state.black.has(i);c.classList.toggle("black",on);c.setAttribute("aria-pressed",String(on));
    c.setAttribute("aria-label","Row "+(Math.floor(i/N)+1)+", column "+(i%N+1)+", "+PUZZLE.letters[i]+(on?", blacked out":""));});
  $("count").textContent=state.black.size;
  $("undoBtn").disabled=!state.hist.length||state.solved;$("clearBtn").disabled=!state.black.size||state.solved;
}
function tap(i){
  if(state.solved)return;
  startTimer();state.taps++;state.hist.push([...state.black]);if(state.hist.length>300)state.hist.shift();
  if(state.black.has(i))state.black.delete(i);else state.black.add(i);
  paint();setMsg("");
  if([...state.black].sort((a,b)=>a-b).join()===ANSWER)return finish();
  if(state.black.size===K){state.misses++;setMsg("Not yet: a row or column doesn’t read as words.");gridEl.classList.remove("shake");void gridEl.offsetWidth;gridEl.classList.add("shake");}
  else if(state.black.size>K)setMsg("That’s more than "+K+".");
  saveCur();
}
$("undoBtn").addEventListener("click",()=>{if(state.solved||!state.hist.length)return;state.black=new Set(state.hist.pop());paint();setMsg("");saveCur();});
$("clearBtn").addEventListener("click",()=>{if(state.solved||!state.black.size)return;state.hist.push([...state.black]);state.black=new Set();paint();setMsg("");saveCur();});
document.addEventListener("keydown",e=>{
  if(state.solved||e.ctrlKey||e.metaKey||e.altKey)return;
  if(document.documentElement.classList.contains("dn-starting"))return;
  if(e.key==="Backspace"||e.key==="z"||e.key==="Z"){$("undoBtn").click();e.preventDefault();}
});

/* ---------- finish ---------- */
function dnStreak(n){n=parseInt(String(n||"").replace(/\D/g,""),10)||0;return n>=2?" · 🔥"+n:"";}
function shareText(){return "⬛ Redact #"+NUM+" — "+timerEl.textContent.trim()+dnStreak(String(state.streak));}
function finish(){
  stopTimer();state.solved=true;document.body.classList.add("win");
  const secs=Math.round(state.secs),t=fmt(secs);
  timerEl.textContent=t;
  cells.forEach((c,i)=>{if(!state.black.has(i))setTimeout(()=>c.classList.add("good"),30*(Math.floor(i/N)+i%N));});
  state.streak=streakBump();$("streakn").textContent=state.streak;
  $("statTime").textContent=t;$("statStreak").textContent=state.streak;
  window.dnCore.putDone(DONE_KEY,PUZZLE.id,{t,s:secs,m:state.misses});clearCur();
  paint();setMsg("Solved in "+t+".");
  finishSheet(true);
  try{document.documentElement.setAttribute("data-dn-done","");}catch(e){}
  $("modal").classList.add("on");   // the tracker reads the result box once it opens
}
function recapNode(){
  const wrap=document.createElement("div"),g=document.createElement("div");g.className="fin-redact";g.style.setProperty("--n",N);
  const black=new Set(PUZZLE.black);
  for(let i=0;i<N*N;i++){const e=document.createElement("i");if(black.has(i))e.className="b";else e.textContent=PUZZLE.letters[i];g.appendChild(e);}
  const w=document.createElement("p");w.className="fin-redact-words";
  w.innerHTML=PUZZLE.words.map(x=>"<b>"+x.toUpperCase()+"</b>").join(" · ");
  wrap.appendChild(g);wrap.appendChild(w);return wrap;
}
function finishSheet(fresh){
  const h2=document.querySelector("#modal h2");if(h2){h2.id="winTitle";h2.textContent="Solved";}
  let played=0;try{const s=readSave();played=s.done?Object.keys(s.done).length:0;}catch(e){}
  const st=streakGet()||{},rec=window.dnCore.getDone(DONE_KEY,PUZZLE.id)||{};
  const m=fresh?state.misses:(+rec.m||0);
  const note=(m?m+" wrong "+(m===1?"try":"tries")+" at the full count.":"Right first time at the full count.")+(fresh&&state.resumed?" Picked up where you left off.":"");
  const share={text:shareText};
  if(LAB)share.url="dailynoodle.co.uk"+location.pathname;
  window.dnFinish.show({type:"redact",id:PUZZLE.id,n:NUM,date:meta("dn:date"),
    box:"modal",title:"winTitle",hero:"statTime",note,share,lab:LAB,
    stats:[{id:"statStreak",label:"day streak"},{value:Math.max(st.best||0,state.streak||0),label:"best streak"},{value:played,label:"boards played"}],
    recap:{title:"The crossword",sub:K+" black squares; every run across and down a word.",node:recapNode()}});
}
function restoreDone(){
  const rec=window.dnCore.getDone(DONE_KEY,PUZZLE.id);if(!rec)return false;
  const t=(/^\d{1,4}:\d{2}$/.test(String(rec.t))?String(rec.t):null)||"0:00";
  state.solved=true;state.black=new Set(PUZZLE.black);
  stopTimer();timerEl.textContent=t;timerEl.classList.remove("waiting");$("statTime").textContent=t;$("statStreak").textContent=state.streak;
  paint();cells.forEach((c,i)=>{if(!state.black.has(i))c.classList.add("good");});document.body.classList.add("win");setMsg("Solved in "+t+".");
  try{document.documentElement.setAttribute("data-dn-done","");}catch(e){}
  finishSheet(false);
  return true;
}
$("closeBtn").addEventListener("click",()=>{$("modal").classList.remove("on");window.dnFinish.hide();});
$("shareBtn").addEventListener("click",()=>{const text=shareText();if(navigator.share)navigator.share({text}).catch(()=>{});else setMsg(text);});

build();
if(!restoreDone()){restoreCur();paint();if(state.resumed)setMsg("Carrying on where you left off.");}
})();
